#!/usr/bin/env python3
"""Generates modifiers.txt: every card of the deck gets an enhancement and a seal.

Card i of the Card pool gets enhancement (i % 8) + 1 and seal i % 5, written with poke8
(struct Card: suit, rank, enhancement, seal, debuffed, face_down, played_ante — 7 bytes).
"""
import os

CARD_SIZE = 7
OFF_ENHANCEMENT = 2
OFF_SEAL = 3

lines = [
    '# Generated by gen_modifiers.py: all 52 cards get an enhancement (i % 8 + 1) and a seal',
    '# (i % 5), then a hand of the 5 leftmost cards is played. Seed GBARU1.',
    'wait 460', 'press START', 'wait 60', 'press A', 'wait 60',
    'pokestr {sym:s_seed_str} GBARU1', 'poke8 {sym:use_seed} 1',
    'press DOWN', 'wait 10', 'press A', 'wait 120',
]
for i in range(52):
    base = i * CARD_SIZE
    lines.append(f'poke8 {{sym:Card_storage+{base + OFF_ENHANCEMENT}}} {i % 8 + 1}')
    lines.append(f'poke8 {{sym:Card_storage+{base + OFF_SEAL}}} {i % 5}')
lines += [
    'shot 00_blind_select',
    'press A', 'wait 180', 'shot 01_hand',
    'press A', 'press RIGHT', 'press A', 'press RIGHT', 'press A', 'press RIGHT', 'press A',
    'press RIGHT', 'press A', 'wait 10', 'shot 02_selected',
    'press L',
]
for t in range(12):
    lines += ['wait 45', f'shot 1{t:x}_scoring']
lines += ['wait 400', 'shot 30_after_hand']

out = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'modifiers.txt')
open(out, 'w').write('\n'.join(lines) + '\n')
print(out)
